 "gaps": [
  {
   "id": "G-C16",
   "title": "C16 is checked after the run, not before each call",
   "affects": [
    "C16"
   ],
   "why": "Cedar keeps no state it could count with (repo gap 8).",
   "impact": "A runaway is detected and alerted, not prevented.",
   "next": "Reserve-then-commit budget check at the gateway."
  },
  {
   "id": "G-C9",
   "title": "C9 is measured per hour, not per run",
   "affects": [
    "C9"
   ],
   "why": "AgentCore publishes hourly aggregates.",
   "impact": "A run's C9 answer is the hour window(s) it fell in.",
   "next": "Per-run latency from gateway timings."
  },
  {
   "id": "G-C9-hour",
   "title": "One hour of IT-agent metrics is missing",
   "affects": [
    "C9"
   ],
   "why": "No datapoint returned for it_resolution_agent at 12:00 UTC (sample).",
   "impact": "Windows including that hour are INDETERMINATE.",
   "next": "Investigate collection; never treat as healthy."
  },
  {
   "id": "gap-2",
   "title": "Who acted: platform records can't tell agents apart",
   "affects": [
    "WHO"
   ],
   "why": "Every call uses one team key; all runtimes share one IAM role.",
   "impact": "Actor comes from the agents' own ledger.",
   "next": "Corroborate with per-runtime records.",
   "source": "gap-list.md#2"
  },
  {
   "id": "gap-3",
   "title": "Agents can use tools they never declared",
   "affects": [
    "WHAT",
    "C7"
   ],
   "why": "The gateway checks the called tool's policy, not the caller's declaration.",
   "impact": "Declarations can't serve as scope.",
   "next": "Report out-of-scope tool calls as findings.",
   "source": "gap-list.md#3"
  },
  {
   "id": "gap-4",
   "title": "Refused calls are recorded as ALLOW",
   "affects": [
    "AUTHORIZED"
   ],
   "why": "Cedar decides before the guardrail and the kill switch act.",
   "impact": "Policy logs overstate allowed calls.",
   "next": "Join each decision to its gateway line.",
   "source": "gap-list.md#4"
  },
  {
   "id": "gap-5",
   "title": "Approvals are self-asserted and don't follow changes",
   "affects": [
    "APPROVED"
   ],
   "why": "Annotation text, empty signature, EKS audit logging off.",
   "impact": "Attestation may not cover what ran.",
   "next": "Record the version each approval covers.",
   "source": "gap-list.md#5"
  },
  {
   "id": "gap-6",
   "title": "The ledger can't show it wasn't altered",
   "affects": [
    "INTEGRITY"
   ],
   "why": "No signatures or hash chain; the write token is readable.",
   "impact": "Integrity by corroboration, not proof.",
   "next": "Cross-check ledger records against platform-written sources.",
   "source": "gap-list.md#6"
  },
  {
   "id": "gap-7",
   "title": "No single durable key joins a run",
   "affects": [
    "RECONSTRUCT",
    "C7"
   ],
   "why": "Durable gateway log has no run id; ledger trace ids are minted by agents.",
   "impact": "Replay needs a multi-step join.",
   "next": "Store the reconstructed timeline per run.",
   "source": "gap-list.md#7"
  },
  {
   "id": "gap-9",
   "title": "Customer data in spans and plain-HTTP traffic",
   "affects": [
    "DATA"
   ],
   "why": "Spans keep full prompts; agents use the plain-HTTP listener.",
   "impact": "Data handling can't be shown as controlled.",
   "next": "Classify the tool; use the TLS listener.",
   "source": "gap-list.md#9"
  },
  {
   "id": "gap-11",
   "title": "A governed tool's code can change under its approval",
   "affects": [
    "APPROVED"
   ],
   "why": "Lambda tools run unpinned code; participants can update it.",
   "impact": "Can't show the approved tool answered.",
   "next": "Record each function's code hash with its approval.",
   "source": "gap-list.md#11"
  },
  {
   "id": "G-L3",
   "title": "ServiceNow-native agent not yet connected",
   "affects": [
    "L3"
   ],
   "why": "In progress.",
   "impact": "Level 3 shows the incident chain but not the ServiceNow agent's analysis.",
   "next": "Arth to connect."
  }
 ],
